// I.AP Normalize Lead (v1.1) — tolerant of LeadConduit field naming. Output is
// the single item every downstream node reads via $('Normalize Lead').
const item = $input.first().json || {};
const body = (item.body && typeof item.body === 'object') ? item.body : {};
const nested = (body.lead && typeof body.lead === 'object') ? { ...body, ...body.lead } : body;

function pick(o, keys){ for (const k of keys){ const v = o ? o[k] : undefined; if (v !== null && v !== undefined && String(v).trim() !== '') return String(v).trim(); } return ''; }

const firstName = pick(nested, ['first_name','firstName','firstname','FirstName']);
const lastName  = pick(nested, ['last_name','lastName','lastname','LastName']);
const rawPhone  = pick(nested, ['phone','phone_1','phone1','Phone','mobile','cell','phone_number']);
const email     = pick(nested, ['email','Email','email_address']).toLowerCase();
const address1  = pick(nested, ['address_1','address1','address','street','Address']);
const city      = pick(nested, ['city','City']);
const state     = pick(nested, ['state','State']);
const zip       = pick(nested, ['postal_code','zip','zipcode','postalCode','Zip']);
// REAL SOURCE. `vendor` must be the exact LP sub-source name (e.g. "Modernize",
// "MyHomePros", "Google PPC Windows") — it is matched against
// lp_source_mapping.lp_source_subdetail by the LP-MCP resolver.
const vendor    = pick(nested, ['vendor','lp_subsource','source','source_name','lead_source','Source']);
// LP parent channel. Default Internet; ActiveProspect may pass lp_source
// ("Affiliates" for Prolific Marketing).
const channel   = pick(nested, ['lp_source','channel','lead_source_parent']) || 'Internet';
const flowName  = pick(nested, ['flow','flow_name','Flow']);
const tfCert    = pick(nested, ['trustedform_cert_url','trustedform','xxTrustedFormCertUrl','trusted_form_cert_url','TrustedForm']);
const apLeadId  = pick(nested, ['ap_lead_id','lead_id','leadconduit_lead_id','event_id','LeadId']);
const lpLeadId      = pick(nested, ['lp_lead_id','lead_perfection_lead_id','lpLeadId']);
const lpProspectId  = pick(nested, ['lp_prospect_id','lead_perfection_prospect_id','lpProspectId']);

const digits = rawPhone.replace(/\D/g, '');
const phone10 = (digits.length === 11 && digits.charAt(0) === '1') ? digits.slice(1) : (digits.length === 10 ? digits : '');
const phoneE164 = phone10 ? '+1' + phone10 : '';

function slug(s){ return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''); }
const vendorSlug = slug(vendor);

// Channel tag — same vocabulary as LP-MCP lp-contact-backstop.js (verified live
// against contacts.tags). Vendor rides a second, non-conflicting detail tag.
const CHANNEL_TAG = { internet: 'source:internet', affiliates: 'source:affiliate', affiliate: 'source:affiliate' };
const channelTag = CHANNEL_TAG[channel.toLowerCase()] || 'source:internet';

// NO entry:* / active-entry:* / intent-bucket:* here. Those are resolved from
// lp_source_mapping by LP-MCP (ensure-routing-tags) after the contact exists.
const tags = [channelTag];
if (vendorSlug && vendorSlug !== slug(channel)) tags.push(channelTag + '-' + vendorSlug);
tags.push('ap-intake-created', 'lp-linked', 'stage:new-lead');

const NAME_JUNK = new Set(['n/a','na','..','...','?','-','.','none','null','unknown','test']);
function clean(s){ const t = String(s || '').replace(/\s+/g, ' ').trim(); return NAME_JUNK.has(t.toLowerCase()) ? '' : t; }

let ok = true, error = '';
if (!phone10) { ok = false; error = 'missing_or_invalid_phone'; }

const stamp = new Date().toISOString().slice(0, 10);
const noteLines = [
  'ActiveProspect lead received ' + stamp + ' (I.AP intake).',
  vendor ? 'Source: ' + vendor + ' (' + channel + ')' : 'Source: not provided by ActiveProspect',
  flowName ? 'Flow: ' + flowName : null,
  tfCert ? 'TrustedForm certificate: ' + tfCert : null,
  apLeadId ? 'ActiveProspect lead id: ' + apLeadId : null,
  'Already delivered to Lead Perfection by ActiveProspect. Do NOT re-send this lead to LP.'
].filter(Boolean);

return [{ json: {
  ok, error, phone10, phoneE164,
  firstName: clean(firstName), lastName: clean(lastName),
  email, address1, city, state, zip,
  vendor, vendorSlug, channel, flowName, tfCert, apLeadId, lpLeadId, lpProspectId,
  tags, note_body: noteLines.join('\n'),
  raw: body, received_at: new Date().toISOString()
} }];

// I.AP Pick Match (v1.1) — find-before-create. Mirrors lp-contact-backstop.js
// pickPhoneMatch: only a VERIFIED last-10 phone match counts. Unverified
// candidates fall through to create; GHL's duplicate-400 then surfaces the
// real contact id (handled in Create Result).
const lead = $('Normalize Lead').first().json;
const res = ($input.first() && $input.first().json) ? $input.first().json : {};
const list = Array.isArray(res.contacts) ? res.contacts : [];
const want = lead.phone10;
function d(s){ return String(s || '').replace(/\D/g, ''); }
let match = null;
for (const c of list) {
  if (!c || !c.id) continue;
  const cp = d(c.phone);
  if (cp && cp.slice(-10) === want) { match = c; break; }
}

if (match) {
  // LINK ONLY. Never re-tag or re-stamp an existing contact from this pipe —
  // it may be mid-conversation or carry deliberate suppression state. LP
  // sync / backstop own LP-id stamping for existing contacts.
  return [{ json: { action: 'link', contact_id: match.id, matched_on: 'phone', existing_tags: match.tags || [] } }];
}

// GHL custom field IDs — canonical: LP-MCP src/entry-source-map.js (LP
// Subsource / LP Source) and src/services/lp-contact-backstop.js (LP ids).
const CF_LP_SUBSOURCE   = 'o8h88WeFST8euBUq3Av6'; // read FIRST by the map-driven resolver
const CF_LP_SOURCE      = 'IvSDubMH0FmZmlCDy5C2'; // parent channel fallback
const LP_LEAD_ID_FIELD    = 'GmAVmW6V9sekD7pVONKr';
const LP_PROSPECT_ID_FIELD = 'ZRQAVrzhtzApzLlHmT87';
const customFields = [];
if (lead.vendor)  customFields.push({ id: CF_LP_SUBSOURCE, field_value: lead.vendor });
if (lead.channel) customFields.push({ id: CF_LP_SOURCE,    field_value: lead.channel });
if (lead.lpLeadId)     customFields.push({ id: LP_LEAD_ID_FIELD,     field_value: String(lead.lpLeadId) });
if (lead.lpProspectId) customFields.push({ id: LP_PROSPECT_ID_FIELD, field_value: String(lead.lpProspectId) });

const createBody = {
  locationId: 'SsBG7j5KQAIP1SFP2Sca',
  firstName: lead.firstName,
  lastName: lead.lastName,
  phone: lead.phoneE164,
  // The real origin — the vendor as ActiveProspect names it. Falls back to the
  // channel only when ActiveProspect sends no source at all.
  source: lead.vendor || lead.channel,
  tags: lead.tags,
  customFields
};
if (lead.email) createBody.email = lead.email;
if (lead.address1) createBody.address1 = lead.address1;
if (lead.city) createBody.city = lead.city;
if (lead.state) createBody.state = lead.state;
if (lead.zip) createBody.postalCode = lead.zip;

return [{ json: { action: 'create', create_body: createBody } }];

// I.AP Create Result — classify the GHL create response.
const r = ($input.first() && $input.first().json) ? $input.first().json : {};
const status = Number(r.statusCode || r.status || 0);
const body = (r.body !== undefined) ? r.body : r;
const text = (() => { try { return JSON.stringify(body); } catch (e) { return String(body); } })();
let contact_id = null, action = 'error', error = '';
if (status >= 200 && status < 300) {
  contact_id = (body && body.contact && body.contact.id) ? body.contact.id : (body && body.id ? body.id : null);
  if (contact_id) action = 'created'; else error = 'no_contact_id_in_response';
} else if (status === 400 && /duplicat/i.test(text)) {
  // GHL server-side dedupe (location disallows duplicates). meta.contactId is
  // the existing contact — link to it, exactly like the backstop's re-search.
  contact_id = (body && body.meta && body.meta.contactId) ? body.meta.contactId : null;
  if (contact_id) action = 'link'; else error = 'duplicate_without_contact_id';
} else {
  error = 'ghl_create_' + status + ': ' + text.slice(0, 300);
}
return [{ json: { action, contact_id, error, status } }];

// I.AP Build Response — whichever branch resolved the contact.
let info = null;
try { const c = $('Create Result').first().json; if (c && c.contact_id) info = { action: c.action, contact_id: c.contact_id }; } catch (e) { info = null; }
if (!info) { const p = $('Pick Match').first().json; info = { action: p.action, contact_id: p.contact_id }; }
const noteRes = ($input.first() && $input.first().json) ? $input.first().json : {};
const noteStatus = Number(noteRes.statusCode || noteRes.status || 0);
let routing = null;
try {
  const r = $('Ensure Routing Tags (LP-MCP)').first().json || {};
  const b = (r.body !== undefined) ? r.body : r;
  routing = { status: b.status || null, active_entry: b.active_entry || null, intent_bucket: b.intent_bucket || null, signal: (b.inferred && b.inferred.signal) || null };
} catch (e) { routing = null; }
const lead = $('Normalize Lead').first().json;
return [{ json: {
  success: true,
  action: info.action,
  contact_id: info.contact_id,
  source_written: lead.vendor || lead.channel,
  routing,
  note_saved: noteStatus >= 200 && noteStatus < 300,
  phone: lead.phoneE164
} }];
